type Invoice struct{ Customer, Total string }          // stage 1: logical page

var htmlTpl = template.Must(template.ParseFiles("invoice.html")) // HTML channel
var textTpl = template.Must(template.ParseFiles("invoice.txt"))  // text channel

func render(channel string, inv Invoice, w io.Writer) error {
    if channel == "html" {
        return htmlTpl.Execute(w, inv)
    }
    return textTpl.Execute(w, inv)
}
